Algorithm 2: Pseudocode for an agent interacting with an environment.
for episode = 0,1,2,... do
    s ~ d0;
    for t = 0 to ∞ do
        a = agent.getAction(s);
        s' ~ p(s,a,·);
        r ~ dR(s,a,s');
        agent.train(s,a,r,s');
        if s' == s∞ then
            break;          // Exit out of loop over time, t
            s = s';
    agent.newEpisode();
